-- Generated by `python -m app.render_sql` from table_mapping.yaml. Do not edit by hand.
-- Monitoring queries. Times are UTC.

-- Jobs by status
SELECT `status`, `event_type`, COUNT(*) AS jobs
FROM `wa_notification_queue`
GROUP BY `status`, `event_type`
ORDER BY `status`, `event_type`;

-- Oldest PENDING job (UTC; minutes waiting)
SELECT COUNT(*) AS pending_jobs,
       MIN(`created_at`) AS oldest_created_utc,
       TIMESTAMPDIFF(MINUTE, MIN(`created_at`), UTC_TIMESTAMP(6)) AS oldest_age_minutes
FROM `wa_notification_queue`
WHERE `status` = 'PENDING';

-- FAILED jobs, newest first
SELECT `id`, `source_record_id`, `event_type`, CONCAT(LEFT(`phone`, 2), 'XXXXX', RIGHT(`phone`, 3)) AS phone,
       `attempt_count`, `last_http_status`, LEFT(`error_message`, 200) AS error,
       `last_attempt_at`, `created_at`
FROM `wa_notification_queue`
WHERE `status` = 'FAILED'
ORDER BY `id` DESC
LIMIT 100;

-- Uncertain jobs: ACL was being called when the worker stopped
SELECT `id`, `source_record_id`, `event_type`, CONCAT(LEFT(`phone`, 2), 'XXXXX', RIGHT(`phone`, 3)) AS phone,
       `attempt_count`, `processing_started_at`, `last_attempt_at`
FROM `wa_notification_queue`
WHERE `status` = 'PROCESSING' AND `last_attempt_at` IS NOT NULL
ORDER BY `id`;
